#!/usr/bin/env node
/**
 * Real screenshots of the real dashboard, for the README.
 *
 * Not mockups. This boots the actual web server against a seeded graph, drives
 * a real headless Chromium, and writes PNGs -- so a screenshot that goes stale
 * is regenerated by running this rather than redrawn by hand, and a screenshot
 * that cannot be produced is a broken dashboard rather than a missing asset.
 *
 * The seed is deliberately the same shape the UI verifier uses: a contradiction,
 * a dead end, a low-confidence finding and a real holdout split, so the pictures
 * show the product doing the things the README claims it does.
 *
 *     npm run screenshots
 */

import { chromium } from 'playwright';
import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync, cpSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'docs', 'media');
const PORT = 3600 + Math.floor(Math.random() * 300);
const BASE = `http://localhost:${PORT}`;
const GRAPH = join(tmpdir(), `token-optimizer-shots-${process.pid}`, 'wiki');

process.env.TOKEN_OPTIMIZER_WIKI_DIR = GRAPH;

/** A graph with enough real structure that the views have something to show. */
async function seed() {
  const { putNode, putEdge, nodeId } = await import('../hooks-core/wiki.mjs');
  const { indexFile } = await import('../hooks-core/staleness.mjs');
  const { record } = await import('../hooks-core/metrics.mjs');

  const src = join(GRAPH, 'src');
  mkdirSync(src, { recursive: true });
  writeFileSync(join(src, 'auth.ts'),
    'export function verify(token) {\n  return token.exp > Date.now();\n}\n\nexport class Session {\n  refresh() { return true; }\n}\n');
  writeFileSync(join(src, 'cache.ts'), 'export function evict(key) {\n  return key;\n}\n');
  writeFileSync(join(src, 'retry.ts'), 'export function backoff(attempt) {\n  return 2 ** attempt;\n}\n');

  for (const file of ['auth.ts', 'cache.ts', 'retry.ts']) indexFile(GRAPH, join(src, file));

  const seeds = [
    ['f1', 'verify() compares exp against the local clock, so clock skew on the node causes spurious 401s for valid tokens', 0.92, 'finding', 'auth.ts'],
    ['f2', 'tried a single shared retry budget across all hosts; it deadlocked under burst load because slow hosts starved fast ones', 0.88, 'failure', 'retry.ts'],
    ['f3', 'the cache is write-back', 0.55, 'finding', 'cache.ts'],
    ['f4', 'the cache is write-through', 0.55, 'finding', 'cache.ts'],
    ['f5', 'chose per-host retry budgets over a global one; rejected global because of the deadlock above', 0.9, 'decision', 'retry.ts'],
    ['f6', 'Session.refresh() is never called from the request path, only from the background sweeper', 0.8, 'map', 'auth.ts'],
    ['f7', 'evict() may be reentrant, but this was not confirmed', 0.25, 'finding', 'cache.ts'],
    ['f8', 'backoff() is exponential with no jitter, so retries synchronise across clients after an outage', 0.86, 'finding', 'retry.ts'],
  ];

  const ids = {};
  for (const [key, claim, confidence, type, file] of seeds) {
    ids[key] = putNode(GRAPH, { kind: 'finding', key, claim, confidence, type });
    putEdge(GRAPH, ids[key], 'derived_from', nodeId('file', join(src, file)));
  }
  putEdge(GRAPH, ids.f3, 'contradicts', ids.f4);
  putEdge(GRAPH, ids.f5, 'supersedes', ids.f2);

  // A real holdout split, so the balance view shows a measured saving rather
  // than a placeholder.
  for (let i = 0; i < 40; i++) record(GRAPH, { kind: 'inject', holdout: false, tokens: 140, downstream: 320 });
  for (let i = 0; i < 12; i++) record(GRAPH, { kind: 'inject', holdout: true, tokens: 0, downstream: 2600 });
  record(GRAPH, { kind: 'harvest', tokens: 900 });
}

async function waitForServer(attempts = 60) {
  for (let i = 0; i < attempts; i++) {
    try {
      if ((await fetch(`${BASE}/api/wiki/status`)).ok) return true;
    } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 500));
  }
  return false;
}

async function main() {
  mkdirSync(OUT, { recursive: true });
  await seed();

  // The built server serves its assets from dist.
  const publicSrc = join(ROOT, 'src', 'dashboard', 'public');
  const publicDest = join(ROOT, 'dist', 'dashboard', 'public');
  if (existsSync(publicSrc)) cpSync(publicSrc, publicDest, { recursive: true });

  const server = spawn(process.execPath, [join(ROOT, 'dist', 'server', 'web-server.js')],
    { cwd: ROOT, stdio: 'ignore', windowsHide: true, env: { ...process.env, PORT: String(PORT) } });

  const browser = await chromium.launch();
  try {
    if (!await waitForServer()) throw new Error(`dashboard did not start on ${BASE}`);

    // ONE THEME, because the dashboard has one. Capturing with colorScheme
    // 'light' produced byte-identical files, so shipping them as light-mode
    // screenshots would have been a small lie in the shop window.
    for (const theme of ['dark']) {
      const context = await browser.newContext({
        viewport: { width: 1440, height: 900 },
        deviceScaleFactor: 2, // retina, so the PNG is crisp on a modern display
        colorScheme: theme,
      });
      const page = await context.newPage();

      /** Brings the graph panel into frame; it otherwise sits below the fold. */
      const focusGraph = async () => {
        try {
          await page.locator('#graph, .graph-panel, .constellation, svg').first()
            .scrollIntoViewIfNeeded({ timeout: 3000 });
        } catch { /* nothing to scroll to */ }
      };

      const shot = async (name) => {
        // Let any entry animation settle so the capture is not a half-drawn frame.
        await page.waitForTimeout(1200);
        await page.screenshot({ path: join(OUT, `${name}.png`), fullPage: false });
        console.log(`captured ${name}.png`);
      };

      await page.goto(`${BASE}/wiki`, { waitUntil: 'networkidle' });

      // SELECT A FINDING FIRST. The focus panel is empty until something is
      // chosen, and a screenshot of the empty state is a screenshot of nothing
      // -- which is exactly the kind of unpolished detail this is meant to fix.
      const firstFinding = page.locator('.finding, .finding-card, [data-node-id]').first();
      try {
        await firstFinding.click({ timeout: 5000 });
      } catch { /* no clickable finding; the wider view is still worth capturing */ }
      await focusGraph();
      await shot(`graph-${theme}`);

      // The constellation view: the whole project at once.
      try {
        await page.getByText('Constellation', { exact: true }).click({ timeout: 5000 });
        await focusGraph();
        await shot(`constellation-${theme}`);
      } catch { /* view unavailable in this build */ }

      // The audit tab, which has a real contradiction to surface.
      try {
        await page.getByText('Audit', { exact: false }).first().click({ timeout: 5000 });
        await shot(`audit-${theme}`);
      } catch { /* tab unavailable in this build */ }

      await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
      await shot(`dashboard-${theme}`);

      await context.close();
    }
  } finally {
    await browser.close();
    server.kill('SIGTERM');
    rmSync(dirname(GRAPH), { recursive: true, force: true });
  }
}

main().catch((error) => {
  console.error(error.stack || error.message || String(error));
  process.exit(1);
});
